#!/usr/bin/env bash
set -e

echo "======================================================="
echo "   Installing Antigravity Protocol for Claude...       "
echo "======================================================="

CLAUDE_DIR="$HOME/.claude"
SKILL_DIR="$CLAUDE_DIR/skills/antigravity-planner"

echo ""
echo "[1/3] Creating directories..."
mkdir -p "$CLAUDE_DIR"
mkdir -p "$SKILL_DIR"
echo "  -> Done."

echo ""
echo "[2/3] Deploying global CLAUDE.md and Planner Skill..."
echo "" | base64 --decode > "$CLAUDE_DIR/CLAUDE.md"
echo "  -> Deployed: $CLAUDE_DIR/CLAUDE.md"

echo "" | base64 --decode > "$SKILL_DIR/SKILL.md"
echo "  -> Deployed: $SKILL_DIR/SKILL.md"

echo ""
echo "[3/3] Copying Custom Instructions to Clipboard..."
INSTRUCTIONS=$(echo "" | base64 --decode)

if command -v pbcopy >/dev/null 2>&1; then
    echo "$INSTRUCTIONS" | pbcopy
    echo "  -> Copied to macOS clipboard!"
elif command -v wl-copy >/dev/null 2>&1; then
    echo "$INSTRUCTIONS" | wl-copy
    echo "  -> Copied to Wayland clipboard!"
elif command -v xclip >/dev/null 2>&1; then
    echo "$INSTRUCTIONS" | xclip -selection clipboard
    echo "  -> Copied to X11 clipboard!"
else
    echo "  -> Clipboard utility not found. Please copy manually from README."
fi

echo ""
echo "======================================================="
echo " [SUCCESS] Antigravity Protocol is completely installed!"
echo "======================================================="
echo "1. Claude Code CLI files have been deployed to: $CLAUDE_DIR"
echo "2. Custom Instructions are in your clipboard."
echo "   -> Open Claude Desktop -> Settings -> Custom Instructions and press Cmd+V / Ctrl+V!"
echo ""
